/*************************************************
* Forward NTT, in-place.
* If input coefficient is at most PARAM_Q in absolute value,
* then output coefficient is at most 10*PARAM_Q in absolute value.
**************************************************/

void ntt(int32_t p[PARAM_N]) {
  int len, start, j, k;
  int32_t zeta, t;

  k = 1;
  for(len = PARAM_N/2; len > 0; len >>= 1) {
    for(start = 0; start < PARAM_N; start = j + len) {
      zeta = zetas[k++];
      for(j = start; j < start + len; ++j) {
        t = montgomery_reduce((int64_t)zeta * p[j + len]);
        p[j + len] = p[j] - t;
        p[j] = p[j] + t;
      }
    }
  }
}

/*************************************************
*Inverse NTT and multiplication by Montgomery factor 2^32.
*If input coefficients are at most 10*PARAM_Q in absolute value
*Output coefficients are smaller than 0.6*PARAM_Q in absolute value.
**************************************************/
void invntt_frominvmont(int32_t p[PARAM_N]) {
  int start, len, j, k;
  int32_t t, zeta;
  
  k = PARAM_N;
  for(len = 1; len < PARAM_N; len <<= 1) {
    for(start = 0; start < PARAM_N; start = j + len) {
		zeta = -zetas[--k];
      for(j = start; j < start + len; ++j) {
        t = p[j];
        p[j] = t + p[j + len];
        p[j + len] = t - p[j + len];
        p[j + len] = montgomery_reduce((int64_t)zeta * p[j + len]);
      }
    }
  }

  for (j = 0; j < PARAM_N; ++j) {
	  p[j] = montgomery_reduce(mont_invn * p[j]);
  }
}
